import assert from 'node:assert/strict';
import {generateKeyPairSync,randomBytes,randomUUID} from 'node:crypto';
import {chmod,mkdir,mkdtemp,readFile,realpath,rm,writeFile} from 'node:fs/promises';
import {createServer,connect,type Socket} from 'node:net';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {setTimeout as delay} from 'node:timers/promises';
import {test} from 'node:test';
import {TrafficChildProcess} from '../../src/traffic-child-process.ts';
import {TrafficSpool} from '../../src/traffic-spool.ts';
import {TrafficChildJournal} from '../../src/traffic-child-journal.ts';
import {signManifest,type ReportingGatewayManifest} from '../../src/manifest.ts';
import {verifyTrafficReport} from '../../src/traffic-report.ts';
import {verifyTrafficLifecycle} from '../../src/traffic-lifecycle.ts';
async function waitFor<T>(read:()=>Promise<T>):Promise<T>{const end=Date.now()+4000;for(;;){try{return await read();}catch(e){if(Date.now()>end)throw e;await delay(10);}}}
test('real paused HAProxy retains both channels and exact tail bytes through signed final closure',async t=>{
 const root=await realpath(await mkdtemp(join(tmpdir(),'hqt-'))),socket=join(root,'stats.sock');const clients=new Set<Socket>();
 const backend=createServer(s=>{clients.add(s);s.once('close',()=>clients.delete(s));s.pipe(s);});await new Promise<void>(r=>backend.listen(19081,'127.0.0.1',r));
 let child:TrafficChildProcess|undefined,staff:Socket|undefined,publicClient:Socket|undefined;
 t.after(async()=>{staff?.destroy();publicClient?.destroy();await child?.stop();for(const s of clients)s.destroy();await new Promise<void>(r=>backend.close(()=>r()));await rm(root,{recursive:true,force:true});});
 const issuer=generateKeyPairSync('ed25519'),reporter=generateKeyPairSync('ed25519'),cellId=randomUUID(),processId=randomUUID(),installationId=randomUUID();
 const startedAt=new Date(Date.now()-1000).toISOString(),route={installationId,venueId:randomUUID(),revision:1,staffHostname:'staff.sol.example.test',publicHostname:'sol.example.test',address:'10.77.0.2',port:19081,peerPublicKey:randomBytes(32).toString('base64')};
 const manifest:ReportingGatewayManifest={version:2,audience:'waitron-cloud-gateway',cellId,sequence:1,issuedAt:Date.parse(startedAt),expiresAt:Date.parse(startedAt)+600000,reporter:{gatewayId:randomUUID(),generation:1},routes:[route]};
 const name=(channel:string)=>`traffic_user_${channel}_${installationId.replaceAll('-','')}`;
 await writeFile(join(root,'haproxy.cfg'),`global\n stats socket ${socket} mode 600 level operator\ndefaults\n mode tcp\n timeout connect 1s\n timeout client 10s\n timeout server 10s\nfrontend ingress\n bind 127.0.0.1:19080\n default_backend ${name('staff')}\nfrontend public_https\n bind 127.0.0.1:19082\n default_backend ${name('public')}\nbackend ${name('staff')}\n server echo 127.0.0.1:19081\nbackend ${name('public')}\n server echo 127.0.0.1:19081\n`);
 const mapping={country:'ES' as const,environment:'test' as const,cellId,directory:join(root,'reports'),writerUid:process.geteuid!(),readerGid:process.getegid!()};await mkdir(mapping.directory,{mode:0o750});await chmod(mapping.directory,0o2750);
 const spool=new TrafficSpool({directory:join(root,'spool'),maxBytes:32768});
 const options={directory:join(root,'journal'),country:'ES' as const,environment:'test' as const,cellId,issuerKey:issuer.publicKey,reporterKey:reporter.privateKey};
 child=new TrafficChildProcess({...options,spool,manifest:signManifest(manifest,issuer.privateKey,Date.parse(startedAt)),processId,startedAt,predecessorId:null,command:'haproxy',args:['-db','-f',join(root,'haproxy.cfg')],socket,mapping,lifetimeSocket:join(root,'unused.sock')});
 await child.start();const pid=child.pid!;t.diagnostic(`owned HAProxy PID ${pid}`);await waitFor(()=>readFile(join(root,'haproxy.cfg')).then(async()=>{const {lstat}=await import('node:fs/promises');return lstat(socket);}));
 const open=async(port:number)=>{const c=connect(port,'127.0.0.1');await new Promise<void>((r,j)=>{c.once('connect',r);c.once('error',j);});return c;};
 const echo=async(c:Socket,text:string)=>{const got=new Promise<Buffer>(r=>c.once('data',r));c.write(text);assert.equal((await got).toString(),text);};
 staff=await open(19080);publicClient=await open(19082);await echo(staff,'before-pause');await echo(publicClient,'public');await child.sample();
 assert.equal(typeof child.finish,'function','real HAProxy requires the quiescent finish path');
 let finished=false;const closing=child.finish().then(()=>{finished=true;});
 await delay(100);assert.equal(finished,false,'live sessions must prevent a final record');
 await echo(staff,'after-pause');await echo(publicClient,'tail');
 const closed=[staff,publicClient].map(c=>new Promise<void>(r=>c.once('close',()=>r())));staff.end();publicClient.end();await Promise.all(closed);await closing;
 assert.equal(child.running,false);assert.throws(()=>process.kill(pid,0),/ESRCH/);assert.equal((await spool.restore()).complete,true);
 const reports=(await spool.pending()).map(e=>verifyTrafficReport(e,reporter.publicKey));assert.equal(reports.length,2);assert.ok(reports.every(r=>r.complete));
 const sums=new Map<string,bigint>();for(const r of reports)for(const e of r.entries)sums.set(e.channel,(sums.get(e.channel)??0n)+BigInt(e.ingress)+BigInt(e.egress));
 assert.deepEqual([...sums],[['staff',46n],['public',20n]]);
 const saved=await new TrafficChildJournal(options).restore();assert.ok(saved?.end);const end=verifyTrafficLifecycle(saved.end,reporter.publicKey);assert.equal(end.finalSequence,2);assert.equal(end.endedAt,reports[1]!.until);
 t.diagnostic('HAProxy TCP fixture: staff 23 ingress + 23 egress; public 10 + 10; final signed sequence 2. TLS/probe/DB/full-renderer qualification remains separate.');
});
